CREATE TABLE public.student_memorization_ranges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES public.students(id) ON DELETE CASCADE,start_ayah integer NOT NULL CHECK(start_ayah BETWEEN 1 AND 6236),end_ayah integer NOT NULL CHECK(end_ayah BETWEEN 1 AND 6236),from_label text NOT NULL,to_label text NOT NULL,active boolean NOT NULL DEFAULT true,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),superseded_at timestamptz,CHECK(end_ayah>=start_ayah));
GRANT ALL ON public.student_memorization_ranges TO service_role;
ALTER TABLE public.student_memorization_ranges ENABLE ROW LEVEL SECURITY;
CREATE INDEX student_memorization_ranges_active_idx ON public.student_memorization_ranges(student_id) WHERE active;
CREATE FUNCTION public.mem_norm(_raw text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT trim(regexp_replace(translate(lower(coalesce(_raw,'')),'٠١٢٣٤٥٦٧٨٩أإآٱىؤئـ','0123456789ااااايوي '),'[\x064B-\x065F\x0670]','','g')) $$;
