CREATE FUNCTION public.mem_hizb_starts() RETURNS integer[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[1,82,149,210,260,308,386,464,517,581,641,696,751,825,900,955,1042,1125,1201,1269,1328,1390,1479,1557,1649,1726,1803,1952,2030,2128,2215,2349,2484,2596,2674,2812,2876,3043,3215,3303,3386,3491,3564,3630,3733,3933,4090,4174,4265,4349,4511,4601,4706,4902,5105,5178,5242,5448,5673,5949,6237]::integer[] $$;
CREATE FUNCTION public.mem_ayah(_raw text) RETURNS integer LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE t text:=public.mem_norm(_raw);m text[];n text;a integer;i integer;names text[]:=ARRAY['الفاتحة','البقرة','آل عمران','النساء','المائدة','الأنعام','الأعراف','الأنفال','التوبة','يونس','هود','يوسف','الرعد','ابراهيم','الحجر','النحل','الإسراء','الكهف','مريم','طه','الأنبياء','الحج','المؤمنون','النور','الفرقان','الشعراء','النمل','القصص','العنكبوت','الروم','لقمان','السجدة','الأحزاب','سبإ','فاطر','يس','الصافات','ص','الزمر','غافر','فصلت','الشورى','الزخرف','الدخان','الجاثية','الأحقاف','محمد','الفتح','الحجرات','ق','الذاريات','الطور','النجم','القمر','الرحمن','الواقعة','الحديد','المجادلة','الحشر','الممتحنة','الصف','الجمعة','المنافقون','التغابن','الطلاق','التحريم','الملك','القلم','الحاقة','المعارج','نوح','الجن','المزمل','المدثر','القيامة','الانسان','المرسلات','النبإ','النازعات','عبس','التكوير','الإنفطار','المطففين','الإنشقاق','البروج','الطارق','الأعلى','الغاشية','الفجر','البلد','الشمس','الليل','الضحى','الشرح','التين','العلق','القدر','البينة','الزلزلة','العاديات','القارعة','التكاثر','العصر','الهمزة','الفيل','قريش','الماعون','الكوثر','الكافرون','النصر','المسد','الإخلاص','الفلق','الناس']::text[];base integer;BEGIN IF t='' OR t~'صفح[ةه]' THEN RETURN NULL;END IF;m:=regexp_match(t,'^(\d{1,3})\s*[:،/]\s*(\d{1,3})$');IF m IS NOT NULL THEN n:=m[1];a:=m[2]::integer;ELSE m:=regexp_match(t,'(\d+)\s*$');IF m IS NULL THEN RETURN NULL;END IF;a:=m[1]::integer;n:=trim(substr(t,1,length(t)-length(m[1])));END IF;n:=regexp_replace(n,'^سور[ةه]\s+','');IF n~'^\d+$' THEN i:=n::integer;ELSE SELECT k INTO i FROM unnest(names) WITH ORDINALITY x(name,k) WHERE public.mem_norm(name)=n OR regexp_replace(public.mem_norm(name),'^ال','')=regexp_replace(n,'^ال','') LIMIT 1;END IF;IF i NOT BETWEEN 1 AND 114 THEN RETURN NULL;END IF;base:=(public.mem_surah_starts())[i];IF a<1 OR base+a>=(public.mem_surah_starts())[i+1] THEN RETURN NULL;END IF;RETURN base+a-1;END $$;
CREATE FUNCTION public.mem_page(_raw text) RETURNS integer LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE t text:=public.mem_norm(_raw);m text[];p integer;BEGIN m:=regexp_match(t,'صفح[ةه]\s*(\d{1,3})');IF m IS NULL THEN RETURN NULL;END IF;p:=m[1]::integer;RETURN CASE WHEN p BETWEEN 1 AND 604 THEN p END;END $$;
CREATE FUNCTION public.mem_segment(_from text,_to text,OUT start_ayah integer,OUT end_ayah integer) LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE fp integer:=public.mem_page(_from);tp integer:=public.mem_page(_to);ps integer[]:=public.mem_page_starts();BEGIN start_ayah:=CASE WHEN fp IS NOT NULL THEN ps[fp] ELSE public.mem_ayah(_from) END;end_ayah:=CASE WHEN tp IS NOT NULL THEN ps[tp+1]-1 ELSE public.mem_ayah(_to) END;IF start_ayah IS NULL AND end_ayah IS NOT NULL THEN start_ayah:=CASE WHEN tp IS NOT NULL THEN ps[tp] ELSE end_ayah END;END IF;IF end_ayah IS NULL AND start_ayah IS NOT NULL THEN end_ayah:=CASE WHEN fp IS NOT NULL THEN ps[fp+1]-1 ELSE start_ayah END;END IF;IF start_ayah IS NULL OR end_ayah IS NULL THEN start_ayah:=NULL;end_ayah:=NULL;ELSIF start_ayah>end_ayah THEN SELECT end_ayah,start_ayah INTO start_ayah,end_ayah;END IF;END $$;
CREATE FUNCTION public.mem_segments(_student uuid) RETURNS TABLE(start_ayah integer,end_ayah integer,source text,source_label text,recorded_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT x.start_ayah,x.end_ayah,'recitation','تسميع يومي',r.created_at FROM public.recitation_records r CROSS JOIN LATERAL public.mem_segment(r.memorized_from,r.memorized_to)x WHERE r.student_id=_student AND x.start_ayah IS NOT NULL UNION ALL SELECT x.start_ayah,x.end_ayah,'annual_plan','محفوظ سابق في الخطة',p.updated_at FROM public.student_annual_plans p CROSS JOIN LATERAL jsonb_array_elements(coalesce(p.previous_memorized_ranges,'[]'::jsonb))g CROSS JOIN LATERAL public.mem_segment(g->>'from',g->>'to')x WHERE p.student_id=_student AND x.start_ayah IS NOT NULL UNION ALL SELECT x.start_ayah,x.end_ayah,'annual_plan','محفوظ سابق في الخطة',p.updated_at FROM public.student_annual_plans p CROSS JOIN LATERAL public.mem_segment(p.previous_memorized_from,p.previous_memorized_to)x WHERE p.student_id=_student AND coalesce(jsonb_array_length(p.previous_memorized_ranges),0)=0 AND x.start_ayah IS NOT NULL UNION ALL SELECT x.start_ayah,x.end_ayah,'madarij','سجل مدارج',d.created_at FROM public.madarij_daily_progress d CROSS JOIN LATERAL regexp_match(coalesce(d.memorization,''),'(.+?)\s+-\s+(.+)')m CROSS JOIN LATERAL public.mem_segment(m[1],m[2])x WHERE d.student_id=_student AND x.start_ayah IS NOT NULL UNION ALL SELECT r.start_ayah,r.end_ayah,'manual','استكمال موثق من ملف الطالب',r.created_at FROM public.student_memorization_ranges r WHERE r.student_id=_student AND r.active $$;
REVOKE ALL ON FUNCTION public.mem_segments(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.mem_completed(_student uuid) RETURNS integer[] LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE seg record;merged jsonb:='[]';cs integer;ce integer;h integer;hs integer[]:=public.mem_hizb_starts();result integer[]:='{}';BEGIN FOR seg IN SELECT start_ayah s,end_ayah e FROM public.mem_segments(_student) ORDER BY start_ayah,end_ayah LOOP IF cs IS NULL THEN cs:=seg.s;ce:=seg.e;ELSIF seg.s<=ce+1 THEN ce:=greatest(ce,seg.e);ELSE merged:=merged||jsonb_build_array(jsonb_build_array(cs,ce));cs:=seg.s;ce:=seg.e;END IF;END LOOP;IF cs IS NOT NULL THEN merged:=merged||jsonb_build_array(jsonb_build_array(cs,ce));END IF;FOR h IN 1..60 LOOP IF EXISTS(SELECT 1 FROM jsonb_array_elements(merged)r WHERE (r->>0)::integer<=hs[h] AND (r->>1)::integer>=hs[h+1]-1) THEN result:=array_append(result,h);END IF;END LOOP;RETURN result;END $$;
REVOKE ALL ON FUNCTION public.mem_completed(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.student_memorization_data(_student_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid;s public.students;h integer;hs integer[]:=public.mem_hizb_starts();completed integer[];partial integer[];sources jsonb;last timestamptz;needs boolean;result jsonb:='[]';plan jsonb;BEGIN FOREACH sid IN ARRAY coalesce(_student_ids,'{}') LOOP SELECT * INTO s FROM public.students WHERE id=sid;IF s.id IS NULL OR NOT public.himmah_view_halaqa(s.halaqa_id) THEN RAISE EXCEPTION 'غير مصرح بعرض بيانات المحفوظ';END IF;completed:=public.mem_completed(sid);partial:='{}';FOR h IN 1..60 LOOP IF NOT h=ANY(completed) AND EXISTS(SELECT 1 FROM public.mem_segments(sid)m WHERE m.start_ayah<=hs[h+1]-1 AND m.end_ayah>=hs[h]) THEN partial:=array_append(partial,h);END IF;END LOOP;SELECT coalesce(jsonb_agg(DISTINCT source_label),'[]'),max(recorded_at) INTO sources,last FROM public.mem_segments(sid);SELECT jsonb_build_object('id',p.id,'academic_year',p.academic_year,'term',p.term,'start_date',p.start_date,'end_date',p.end_date,'daily_memorization_pages',p.daily_memorization_pages) INTO plan FROM public.student_annual_plans p WHERE p.student_id=sid AND p.status='active' ORDER BY p.created_at DESC LIMIT 1;needs:=coalesce((SELECT b.baseline_pages>0 AND NOT EXISTS(SELECT 1 FROM public.mem_segments(sid)m WHERE m.source IN('annual_plan','manual')) FROM public.student_memorization_baseline b WHERE b.student_id=sid),false) OR (completed='{}' AND partial='{}' AND (coalesce(s.total_memorized_pages,0)>0 OR length(trim(coalesce(s.memorization_amount,'')))>0));result:=result||jsonb_build_object('student_id',sid,'student_name',s.full_name,'halaqa_id',s.halaqa_id,'completed',completed,'partial',partial,'sources',sources,'last_updated',last,'needs_completion',needs,'plan',plan);END LOOP;RETURN result;END $$;
REVOKE ALL ON FUNCTION public.student_memorization_data(uuid[]) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.student_memorization_data(uuid[]) TO authenticated;
CREATE FUNCTION public.himmah_eligible_students(_day uuid,_halaqa_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s record;d jsonb;result jsonb:='[]';BEGIN IF NOT public.himmah_admin() OR NOT EXISTS(SELECT 1 FROM public.himmah_days WHERE id=_day) THEN RAISE EXCEPTION 'غير مصرح أو اليوم غير موجود';END IF;FOR s IN SELECT st.id,h.name halaqa_name FROM public.students st JOIN public.halaqat h ON h.id=st.halaqa_id WHERE st.halaqa_id=ANY(coalesce(_halaqa_ids,'{}')) AND st.status='active' ORDER BY st.full_name LOOP d:=public.student_memorization_data(ARRAY[s.id])->0;result:=result||jsonb_build_array(d||jsonb_build_object('halaqa_name',s.halaqa_name,'eligible',jsonb_array_length(d->'completed')>0,'reason',CASE WHEN jsonb_array_length(d->'completed')>0 THEN NULL WHEN (d->>'needs_completion')::boolean THEN 'يحتاج استكمال بيانات المحفوظ' ELSE 'لا يوجد حزب مكتمل الحفظ' END));END LOOP;RETURN result;END $$;
REVOKE ALL ON FUNCTION public.himmah_eligible_students(uuid,uuid[]) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.himmah_eligible_students(uuid,uuid[]) TO authenticated;
CREATE FUNCTION public.student_himmah_history(_student uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.students s WHERE s.id=_student AND public.himmah_view_halaqa(s.halaqa_id)) THEN RAISE EXCEPTION 'غير مصرح بعرض سجل الطالب';END IF;RETURN coalesce((SELECT jsonb_agg(to_jsonb(a)||jsonb_build_object('attempt_id',a.id,'day_id',d.id,'day_title',d.title,'day_date',d.day_date,'halaqa_name_at_day',p.halaqa_name,'reviewer_name',r.full_name,'latest_approved',a.approved_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.himmah_attempts n WHERE n.participant_id=a.participant_id AND n.hizb=a.hizb AND n.approved_at>a.approved_at)) ORDER BY d.day_date DESC,a.approved_at DESC NULLS LAST,a.started_at DESC) FROM public.himmah_attempts a JOIN public.himmah_participants p ON p.id=a.participant_id JOIN public.himmah_days d ON d.id=p.day_id LEFT JOIN public.himmah_reviewers r ON r.id=a.reviewer_id WHERE p.student_id=_student),'[]'::jsonb);END $$;
REVOKE ALL ON FUNCTION public.student_himmah_history(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.student_himmah_history(uuid) TO authenticated;
CREATE FUNCTION public.student_save_memorization_ranges(_student uuid,_ranges jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e jsonb;a integer;b integer;n integer:=0;role text;BEGIN IF jsonb_typeof(coalesce(_ranges,'[]'))<>'array' OR jsonb_array_length(_ranges) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'أدخل نطاقًا واحدًا صحيحًا على الأقل';END IF;SELECT get_staff_role(auth.uid()) INTO role;IF NOT EXISTS(SELECT 1 FROM public.students s WHERE s.id=_student AND public.himmah_view_halaqa(s.halaqa_id)) OR role NOT IN('manager','supervisor','assistant_supervisor','teacher','assistant_teacher') THEN RAISE EXCEPTION 'غير مصرح بتعديل محفوظ الطالب';END IF;FOR e IN SELECT * FROM jsonb_array_elements(_ranges) LOOP a:=(e->>'start_ayah')::integer;b:=(e->>'end_ayah')::integer;IF a NOT BETWEEN 1 AND 6236 OR b NOT BETWEEN a AND 6236 OR length(trim(coalesce(e->>'from_label','')))=0 OR length(trim(coalesce(e->>'to_label','')))=0 THEN RAISE EXCEPTION 'نطاق المحفوظ غير صحيح';END IF;END LOOP;UPDATE public.student_memorization_ranges SET active=false,superseded_at=now() WHERE student_id=_student AND active;FOR e IN SELECT * FROM jsonb_array_elements(_ranges) LOOP INSERT INTO public.student_memorization_ranges(student_id,start_ayah,end_ayah,from_label,to_label,created_by) VALUES(_student,(e->>'start_ayah')::integer,(e->>'end_ayah')::integer,left(e->>'from_label',160),left(e->>'to_label',160),auth.uid());n:=n+1;END LOOP;RETURN jsonb_build_object('saved',n,'completed',public.mem_completed(_student));END $$;
REVOKE ALL ON FUNCTION public.student_save_memorization_ranges(uuid,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.student_save_memorization_ranges(uuid,jsonb) TO authenticated;